contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address receiver) public {
        require(receiver != address(0), "zero receiver");
        require(amount > 0, "zero amount");

        uint256 beforeUsdcBal = c.usdcBalance(receiver);
        uint256 beforeUnclaimed = c.unclaimedShares(receiver);
        uint256 beforeRound = c.currentRound();

        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("depositUsdc(uint256,address)", amount, receiver)
        );

        uint256 afterUsdcBal = c.usdcBalance(receiver);
        uint256 afterUnclaimed = c.unclaimedShares(receiver);
        uint256 afterRound = c.currentRound();

        if (ok) {
            uint256 expectedUsdc;
            if (beforeRound < afterRound || beforeUsdcBal == 0 || beforeUnclaimed > afterUnclaimed) {
                expectedUsdc = amount;
            } else {
                expectedUsdc = amount;
            }
            assert(afterUsdcBal + afterUnclaimed >= beforeUsdcBal + beforeUnclaimed + amount);
            assert(afterRound == beforeRound);
        } else {
            assert(afterUsdcBal == beforeUsdcBal);
        }
    }
}

contract InvMutTest {
