        } catch {
            reverted = true;
        }

        uint256 afterUsdcBal = c.usdcBalance(receiver);
        uint256 afterUnclaimed = c.unclaimedShares(receiver);
        uint256 afterRound = c.currentRound();

        if (!reverted) {
            assert(afterUsdcBal + afterUnclaimed == beforeUsdcBal + beforeUnclaimed + amount && afterRound == beforeRound);
        } else {
            assert(afterUsdcBal == beforeUsdcBal && afterUnclaimed == beforeUnclaimed && afterRound == beforeRound);
        }
    }
}

